DROP TABLE IF EXISTS `of_restaurant`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `of_restaurant` (
  `ID` bigint NOT NULL,
  `restaurantUserId` bigint DEFAULT NULL,
  `restaurantUserName` varchar(225) DEFAULT NULL,
  `restaurantId` bigint DEFAULT NULL,
  `restaurantName` varchar(225) DEFAULT NULL,
  `address` varchar(225) DEFAULT NULL,
  `city` varchar(225) DEFAULT NULL,
  `description` varchar(225) DEFAULT NULL,
  `rating` varchar(225) DEFAULT NULL,
  `image` varchar(225) DEFAULT NULL,
  `createdBy` varchar(225) DEFAULT NULL,
  `modifiedBy` varchar(225) DEFAULT NULL,
  `createdDatetime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `modifiedDatetime` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `contectNo` varchar(225) DEFAULT NULL,
  PRIMARY KEY (`ID`),
  KEY `FK_of_restaurant` (`restaurantUserId`),
  CONSTRAINT `FK_of_restaurant` FOREIGN KEY (`restaurantUserId`) REFERENCES `of_user` (`ID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
